                ["Diese Sparten-Finanzanalyse enthaelt mehrere Waehrungen. Die Summary-Karten mit `Mixed` addieren lokale Werte numerisch; fuer belastbare Prozentwerte bitte eine einzelne Waehrung oder ein einzelnes Land filtern."] = "Este análisis financiero de la división contiene varias monedas. Las tarjetas de resumen marcadas como \"Mixto\" agregan valores locales numéricamente; filtre a una moneda o un país para obtener porcentajes confiables.",
