                ["Keine SAP Gateway Zugangsdaten gepflegt."] = "No se mantienen credenciales de SAP Gateway.",
                ["SAP OData Verbindung erfolgreich."] = "Conexión SAP OData exitosa.",
                ["SAP OData Verbindung fehlgeschlagen"] = "La conexión de SAP OData falló",
                ["Kaskadierung Lieferant / Jahr"] = "Cascada de proveedores/año",
                ["Lieferant aufklappen zeigt den Spend nach Warengruppe, Warengruppe aufklappen die einzelnen Materialnummern. Warengruppe aus dem Materialstamm (MARA-MATKL), Fallback Beleg-Warengruppe. Je Warengruppe werden die 25 groessten Materialien gezeigt, der Rest steht in \"uebrige\"."] = "La ampliación de un proveedor muestra el gasto por grupo de materiales; Al expandir un grupo de materiales se muestran los números de material individuales. Grupo de materiales del maestro de materiales (MARA-MATKL), respaldo al grupo de documentos. Por grupo de materiales se muestran los 25 materiales más grandes, el resto está en \"uebrige\".",
                ["Warengruppen auf-/zuklappen"] = "Expandir/contraer grupos de materiales",
                ["Materialnummern auf-/zuklappen"] = "Expandir/contraer números de materiales",
                ["Live + Analyse"] = "En vivo + análisis",
                ["Simulation aktiv"] = "Simulación activa",
                ["Wartet auf SAP"] = "Esperando a SAP",
                ["Spend-Aufriss (mehrstufig)"] = "Desglose de gastos (varios niveles)",
                ["Perspektive waehlen, dann stufenweise aufklappen. Je Ebene sind die groessten Positionen einzeln, der Rest steckt in einer 'uebrige'-Zeile - die Elternsumme bleibt dadurch die Summe ihrer Kinder. Warengruppe aus Materialstamm (MARA-MATKL), Fallback Bestellbeleg."] = "Elija una perspectiva y luego expanda nivel por nivel. Cada nivel enumera las posiciones más grandes individualmente, el resto se agrupa en una fila \"restante\", por lo que el total principal siempre es igual a la suma de sus hijos. Grupo de materiales del maestro de materiales (MARA-MATKL), documento de compra alternativo.",
                ["Live aus Einkauf-Cache"] = "En vivo desde la compra de caché",
                ["Einstieg:"] = "Punto de entrada:",
                ["Ebenen"] = "Niveles",
                ["Noch keine Spend-Daten im gewaehlten Zeitraum. Einkauf-Full-Load ausfuehren oder Zeitraum anpassen."] = "Aún no hay datos de gastos en el período seleccionado. Ejecute una carga completa de compras o ajuste el período.",
                ["Naechste Ebene auf-/zuklappen"] = "Expandir/contraer el siguiente nivel",
                ["Kuchen je Warengruppe: Anteil nach Beschaffungsregion"] = "Pastel por grupo de materiales: participación por región de adquisición",
                ["Je Top-Warengruppe der CHF-Anteil je Lieferantenland. Region = Land des Lieferanten (LFA1-Land1)."] = "Por grupo de materiales principales, la proporción de CHF por país proveedor. Región = país proveedor (LFA1 Land1).",
                ["Lieferantenland (SupplierCountry) ist im Cache noch leer. Die Kuchen fuellen sich mit dem naechsten Einkauf-Full-Load."] = "El país del proveedor todavía está vacío en la memoria caché. Los pasteles se llenan con la siguiente carga completa de compra.",
