                ["Misst Preisreduktionen, vermiedene Preissteigerungen und realisierte Einsparung pro Massnahme."] = "Misura le riduzioni di prezzo, gli aumenti evitati e i risparmi realizzati per iniziativa.",
                ["EKPO, Massnahmenliste, FX"] = "Einkaufserfolg sichtbar machen",
                ["make purchasing impact visible"] = "Konzept",
                ["Bestellrhythmus"] = "Cadenza dell'ordine",
                ["Erkennt Kleinstbestellungen, zu haeufige Bestellungen und Buendelungspotenzial pro Artikel/Lieferant."] = "Rileva ordini piccoli, ordini troppo frequenti e potenziale raggruppamento per articolo/fornitore.",
                ["1. Live-Probe zu Vollaggregation"] = "1. Campione vivo fino all'aggregazione completa",
                ["EKPO/EKET liefern Daten; jetzt braucht es saubere Jahres-/Periodenaggregation."] = "EKPO/EKET ora forniscono dati; la successiva è l'aggregazione anno/periodo pulita.",
                ["2. Preisentwicklung aktivieren"] = "2. Attiva l'andamento dei prezzi",
                ["PowerBI nutzt Min(EKPO.Netwr CHF/Stk); diese Logik ist jetzt lokal nachgebaut."] = "Power BI utilizza Min(EKPO.Netwr CHF/unità); questa logica è ora ricostruita localmente.",
                ["3. Liefertermin-Risiko anzeigen"] = "3. Mostra il rischio della data di scadenza della consegna",
                ["EKET offene Mengen und Termine sind die beste operative Fruehwarnung."] = "Le quantità e le date aperte di EKET rappresentano il miglior preavviso operativo.",
                ["4. Lieferantenrisiko aufbauen"] = "4. Aumentare il rischio dei fornitori",
                ["Kombiniert Performance, offene Werte, Konzentration und Abhaengigkeit."] = "Combina prestazioni, valori aperti, concentrazione e dipendenza.",
                ["5. Contract Cockpit ausbauen"] = "5. Estendere la cabina di pilotaggio del contratto",
                ["Mengenkontrakte und Restverpflichtungen brauchen klare fachliche Abgrenzung."] = "I contratti quantitativi e gli impegni rimanenti necessitano di una chiara separazione funzionale.",
                ["ideen/datenservice"] = "Echter Einkauf-Datenservice",
                ["Real purchasing data service"] = "Grundlage fuer alle echten Einkaufskennzahlen.",
                ["Foundation for all real purchasing KPIs."] = "L'attuale Live-Probe verrà visualizzato su un bel blocco di aggregazioni, poiché tutte le altre idee non sono visualizzate su `$top=1000`, ma sono visualizzate su tutti i periodi.",
                ["The current live sample is expanded into a reliable aggregation layer so all later ideas run on full period values instead of `$top=1000`."] = "EKKOSet, EKPOSet, eketSet, Zeitraumfilter, Belegart, Lieferant, Warengruppe, Artikel",
                ["Spend CHF, offene Menge, offener Wert, Kontraktwert, Beleganzahl, Lieferantenanzahl, letzter Refresh."] = "spesa in CHF, quantità aperta, valore aperto, valore del contratto, conteggio degli ordini, conteggio dei fornitori, ultimo aggiornamento.",
                ["Service/Cache fuer periodische Aggregation bauen; Filter fuer Jahr/Von-Bis/Lieferant/Warengruppe; Belegarten fuer Bestellung vs. Kontrakt trennen."] = "Costruire servizio/cache per l'aggregazione periodica; filtri per anno/da-a/fornitore/gruppo materiale; tipi di documenti separati per ordine e contratto.",
                ["Naechster Schritt: Datenmodell fuer Aggregation definieren und EKPO/EKET Vollabzug gegen SAP testen."] = "Passaggio successivo: definire il modello dei dati di aggregazione e testare l'estrazione completa di EKPO/EKET rispetto a SAP.",
                ["Startpunkt"] = "punto di partenza",
                ["Aggregationsmodell"] = "Modello di aggregazione",
                ["Zieltabelle oder Cache fuer Spend, offene Werte und offene Mengen definieren."] = "definire la tabella o la cache di destinazione per la spesa, i valori aperti e le quantità aperte.",
                ["Filterlogik"] = "Logica del filtro",
                ["Jahr, Von/Bis, Lieferant, Warengruppe und Artikel als Standardfilter vorbereiten."] = "preparare anno, da/a, fornitore, gruppo di materiali e articolo come filtri standard.",
                ["Performance"] = "Prestazioni",
                ["Dashboard liest Aggregatwerte, nicht bei jedem Seitenaufruf alle SAP-Zeilen."] = "il dashboard legge i valori aggregati anziché tutte le righe SAP su ogni richiesta di pagina.",
                ["ideen/liefertermin-risiko"] = "Liefertermin-Risiko",
                ["Delivery due-date risk"] = "Sofortnutzen aus EKET.",
                ["Immediate value from EKET."] = "Offene Mengen und Werte werden nach Faelligkeit klassiert, damit Rueckstaende und kurzfristige Risiken pro Lieferant/Artikel sichtbar werden.",
                ["Open quantities and values are classified by due date so delays and short-term risks by supplier/article become visible."] = "EKET.Eindt, EKET.Menge, EKET.Wemng, EKPO.Netwr, EKPO.Menge, EKKO.Lifnr",
                ["Ueberfaelliger offener Wert, offene Menge 7/30 Tage, Terminampel, Rueckstandsquote."] = "valore aperto scaduto, quantità aperta 7/30 giorni, semaforo scadenza, tasso scaduto.",
                ["Offenmenge = EKET.Menge - EKET.Wemng; Bewertung mit EKPO-Stueckwert; EINDT gegen Heute in Klassen einteilen."] = "quantità aperta = EKET.Menge - EKET.Wemng; valore con prezzo unitario EKPO; classificare l'EINDT rispetto a oggi.",
                ["Naechster Schritt: eigene Seite mit Faelligkeitskalender, Rueckstands-Hotlist und Lieferant/Artikel-Drilldown bauen."] = "Passaggio successivo: creare la propria pagina con il calendario delle scadenze, la hotlist dei prodotti scaduti e il dettaglio dei fornitori/articoli.",
                ["Datumsklassen"] = "Secchi di date",
                ["Ueberfaellig, 0-7 Tage, 8-30 Tage und spaeter als Standardklassen."] = "in ritardo, 0-7 giorni, 8-30 giorni e successivi come classi standard.",
                ["Bewertung"] = "Valutazione",
                ["Offene EKET-Mengen mit EKPO-Netto-Stueckwert bewerten."] = "valore delle quantità EKET aperte con il prezzo unitario netto EKPO.",
                ["Drilldown"] = "Approfondimento",
                ["Von Lieferant zu Artikel und Bestellbeleg navigieren."] = "passare dal fornitore all'articolo e all'ordine d'acquisto.",
                ["ideen/preisabweichung"] = "Preisentwicklung CHF",
                ["Price trend CHF"] = "PowerBI-Logik per articolo/anno.",
                ["Power BI logic by article/year."] = "Minimo Netto-Stueckpreis wird pro Artikel und Jahr sichtbar gemacht.",
                ["Minimum net unit price is shown by article and year."] = "EKPO.Netwr, EKPO.Menge, EKPO.Matnr, EKKO.Bedat, EKKO.Lifnr, FX/Budgetkurse",
                ["Min(Netwr CHF/Stk), Artikel, Jahr, Lieferantenslicer."] = "Min(Netwr CHF/unità), articolo, anno, affettatore fornitore.",
                ["Netto-Stueckpreis als Netwr/Menge bilden und Minimum je Artikel/Jahr ausweisen."] = "calcolare il prezzo unitario netto come Netwr/quantità e mostrare il minimo per articolo/anno.",
                ["Naechster Schritt: Lieferantennamen aus Data-Quelle mitcachen."] = "Passaggio successivo: memorizzare nella cache i nomi dei fornitori dall'origine dati.",
                ["Preisnormalisierung"] = "Normalizzazione dei prezzi",
                ["Preis pro Einheit stabil aus NETWR/MENGE bilden."] = "derivare il prezzo unitario stabile da NETWR/MENGE.",
                ["PowerBI nutzt EKKO.Bedat Jahr als Spalte."] = "Power BI usa EKKO.Bedat anno come colonna.",
                ["Minimum"] = "Minimo",
                ["PowerBI aggregiert mit Min(Netwr CHF/Stk)."] = "Power BI aggrega con Min(Netwr CHF/unità).",
                ["ideen/spend-konzentration"] = "Concentrazione di spesa",
                ["Spend concentration"] = "Lieferantenabhaengigkeit und Buendelungspotenzial.",
                ["Supplier dependency and bundling potential."] = "Spende wird nach Lieferant und Warengruppe verdichtet, um Top-Lieferantenanteile, Single-Source-Risiken und Fragmentierung sichtbar zu machen.",
                ["Spend is aggregated by supplier and material group to show top supplier shares, single-source risks and fragmentation."] = "EKPO.Netwr, EKPO.Matkl, EKKO.Lifnr, Lieferantenname, Warengruppentext",
                ["Top-10-Anteil, Lieferantenanzahl je Warengruppe, Single-Source-Wert, Spend-Pareto."] = "quota dei primi 10, numero di fornitori per gruppo di materiali, valore da un'unica fonte, spesa Pareto.",
                ["Spend je Warengruppe sortieren, kumulierten Anteil berechnen und Lieferantenkonzentration klassieren."] = "ordinare la spesa per gruppo di materiali, calcolare la quota cumulativa e classificare la concentrazione dei fornitori.",
                ["Naechster Schritt: Pareto-Ansicht und Treemap fuer Lieferant/Warengruppe bauen."] = "Passaggio successivo: creare la vista Pareto e la mappa ad albero per il gruppo fornitore/materiale.",
                ["Pareto"] = "Pareto",
                ["Top-N Lieferanten und kumulierten Spend-Anteil berechnen."] = "calcolare i fornitori top-N e la quota di spesa cumulativa.",
                ["Fragmentierung"] = "Frammentazione",
                ["Viele kleine Lieferanten pro Warengruppe markieren."] = "contrassegnare molti piccoli fornitori per gruppo di materiali.",
                ["Buendelung"] = "Raggruppamento",
                ["Warengruppen mit hohem Buendelungspotenzial hervorheben."] = "evidenziare i gruppi di materiali con un elevato potenziale di raggruppamento.",
                ["ideen/datenqualitaet"] = "Datenqualitaet Einkauf",
                ["Purchasing data quality"] = "Vertrauen in die Einkaufskennzahlen sichern.",
                ["Secure trust in purchasing KPIs."] = "Fehlende Stammdaten und Mapping-Luecken werden als eigene Qualitaetskennzahlen angezeigt, damit falsche Analysen frueh auffallen.",
                ["Missing master data and mapping gaps are shown as dedicated quality KPIs so wrong analyses are detected early."] = "EKKO, EKPO, EKET, Lieferantenmapping, Warengruppenmapping, Artikeltext",
                ["Mapping-Abdeckung %, fehlende Warengruppe, fehlender Artikeltext, fehlender Lieferant, Nullpreis."] = "% copertura mappatura, gruppo materiali mancante, testo articolo mancante, fornitore mancante, prezzo zero.",
                ["Pflichtfelder zaehlen, Leerwerte klassieren, Mappingtreffer berechnen und Fehler nach Auswirkung priorisieren."] = "contare i campi obbligatori, classificare i valori vuoti, calcolare i risultati della mappatura e dare priorità agli errori in base all'impatto.",
                ["Naechster Schritt: Pflichtfeldkatalog fuer Einkauf definieren und Datenqualitaetsampel bauen."] = "Passaggio successivo: definire l'acquisto del catalogo dei campi richiesti e creare un semaforo sulla qualità dei dati.",
                ["Pflichtfelder"] = "Campi obbligatori",
                ["Ebeln, Ebelp, Matnr, Matkl, Menge, Netwr, Lifnr pruefen."] = "controlla Ebeln, Ebelp, Matnr, Matkl, Menge, Netwr, Lifnr.",
                ["Mappingquote"] = "Tasso di mappatura",
                ["Warengruppen- und Lieferantenmapping pro Quelle messen."] = "misurare il gruppo di materiali e la mappatura dei fornitori per fonte.",
                ["Fehlerwirkung"] = "Impatto dell'errore",
                ["Fehler nach betroffenem Spend oder offenem Wert priorisieren."] = "dare priorità agli errori in base alla spesa interessata o al valore aperto.",
                ["Abhaengigkeit und Lieferfaehigkeit in einem Score."] = "Dipendenza e capacità di consegna in un unico punteggio.",
                ["Einen fruehen Warnindikator fuer kritische Lieferanten schaffen, bevor offene Termine oder Single-Source-Abhaengigkeit operativ eskalieren."] = "Creare un indicatore di allerta precoce per i fornitori critici prima che i programmi aperti o la dipendenza da un'unica fonte si intensifichino a livello operativo.",
                ["EKKO, EKPO, EKET, Lieferantenstamm, optional Reklamationen"] = "Risiko-Score 0-100, Top-10-Abhaengigkeit, offener Wert je Lieferant, ueberfaellige Menge.",
                ["risk score 0-100, top-10 dependency, open value by supplier, overdue quantity."] = "Gewichtung aus Spend-Anteil, Anzahl offenen Belegen, Terminrueckstand, Single-Source-Hinweis und Datenqualitaet.",
                ["Weighted score from spend share, open order count, schedule delay, single-source marker and data quality."] = "Ampelmatrix Lieferant x Warengruppe, Risiko-Hotlist, 3D-Raum Spend/Rueckstand/Score.",
                ["traffic-light matrix supplier x material group, risk hotlist, 3D space spend/delay/score."] = "Naechster Schritt: EKPO/EKET Vollaggregation pro Lieferant aufbauen und Score-Gewichtung fachlich mit Einkauf festlegen.",
                ["PowerBI-Preislogik nach Artikel und Jahr."] = "Logica dei prezzi di Power BI per articolo e anno.",
                ["Minimum Netto-Stueckpreis wie in PowerBI transparent machen."] = "Rendere trasparente il prezzo unitario netto minimo come in Power BI.",
                ["EKPO.Netwr, EKPO.Menge, EKPO.Matnr, EKPO.Txz01, EKKO.Bedat"] = "Min(Netwr CHF/Stk), Artikel, Jahr, Lieferantenslicer.",
                ["Min(Netwr CHF/unit), article, year, supplier slicer."] = "Stueckpreis = Netto / Menge, danach Minimum je Artikel/Jahr wie PowerBI.",
                ["Unit price = net / quantity, then minimum by article/year like Power BI."] = "Pivot nach Jahr, Artikel-Hotlist, Verlaufslinie je Artikel.",
                ["pivot by year, article hotlist, trend line by article."] = "Naechster Schritt: Lieferanten- und Warengruppennamen aus Data/Data2 als Mapping anbinden.",
                ["Einkauf ausserhalb Standards erkennen."] = "Rileva acquisti al di fuori degli standard.",
                ["Bestellungen sichtbar machen, die ausserhalb bevorzugter Lieferanten, Kontrakte oder Warengruppenregeln laufen."] = "Mostra gli ordini che esulano dai fornitori preferiti, dai contratti o dalle regole del gruppo di materiali.",
                ["EKKO, EKPO, Kontrakte, Preferred-Supplier-Liste"] = "Maverick-Anteil %, Wert ausserhalb Vertrag, Anzahl Regelverletzungen, betroffene Warengruppen.",
                ["maverick share %, value outside contract, rule violation count, affected material groups."] = "Bestellpositionen gegen Vertrags-/Preferred-Supplier-Regeln matchen und Abweichungen grouperen.",
                ["Match order items against contract/preferred-supplier rules and group deviations."] = "Compliance-Funnel, Abweichungstabelle, Heatmap Einkaeufer x Warengruppe.",
                ["compliance funnel, deviation table, heatmap purchaser x material group."] = "Naechster Schritt: Preferred-Supplier- und Vertragsregeln als Stammdatenquelle definieren.",
                ["Next step: define preferred supplier and contract rules as master-data source."] = "Konzept",
                ["Kontrakte, Abrufe und Restmengen steuern."] = "Gestisci contratti, richiami e quantità rimanenti.",
                ["Mengenkontrakte so auswerten, dass Restmenge, Restwert und Verfallsrisiko aktiv steuerbar werden."] = "Valuta i contratti di quantità in modo che la quantità rimanente, il valore residuo e il rischio di scadenza diventino gestibili.",
                ["EKKO, EKPO, EKET, Vertragsbelegarten"] = "Abrufquote %, Restmenge, Restwert CHF, Laufzeit, faellige Verpflichtung.",
                ["consumption rate %, remaining quantity, remaining value CHF, term, due commitment."] = "Kontraktpositionen von normalen Bestellungen trennen und EKET-Mengen gegen Bestell-/Abrufmenge rechnen.",
                ["Separate contract items from normal orders and calculate EKET quantities against ordered/called-off quantity."] = "Kontrakt-Cockpit, Ampel Restlaufzeit, Lieferant/Artikel-Ranking.",
                ["contract cockpit, remaining-term traffic light, supplier/article ranking."] = "Naechster Schritt: SAP-Belegarten und Kennzeichen fuer Kontrakte mit Einkauf/SAP klaeren.",
                ["Cash-Wirkung offener Bestellungen prognostizieren."] = "Previsione dell'effetto cassa degli ordini aperti.",
                ["Aus offenen Bestellungen und Faelligkeiten ableiten, wann Einkaufs-Cash-Abfluss oder Lageraufbau zu erwarten ist."] = "Utilizzare gli ordini aperti e le date di scadenza per ricavare il flusso di cassa di acquisto previsto o l'accumulo di inventario.",
                ["EKPO, EKET, FI/AP, Zahlungsbedingungen"] = "Previsioni di cassa CHF, faelliger offener Wert, Rueckstandswert, Monatsbedarf.",
                ["cash forecast CHF, due open value, overdue value, monthly requirement."] = "Offenen Wert aus EKET/EKPO berechnen und nach Faelligkeitsmonat plus Zahlungsziel verschieben.",
                ["Calculate open value from EKET/EKPO and shift by due month plus payment terms."] = "Monatskurve, Cash-Kalender, Lieferant mit groesster Cash-Wirkung.",
                ["monthly curve, cash calendar, supplier with highest cash impact."] = "Naechster Schritt: Zahlungsbedingungen/FI-Quelle anbinden oder zunaechst mit Standard-Zahlungsziel simulieren.",
                ["Next step: connect payment terms/FI source or start with standard payment-term simulation."] = "Konzept",
                ["Luecken in Einkaufsdaten sichtbar machen."] = "Rendere visibili le lacune nei dati di acquisto.",
                ["Fehlende oder falsche Stammdaten erkennen, damit Kennzahlen belastbar werden."] = "Rileva dati anagrafici mancanti o errati in modo che i KPI diventino affidabili.",
