                ["HR-Ampel fasst Fluktuation, Krankheit, GLZ, Restferien und Datenqualitaet zusammen."] = "एचआर स्थिति टर्नओवर, बीमारी, समय संतुलन, अवकाश संतुलन और डेटा गुणवत्ता का सारांश प्रस्तुत करती है।",
                ["GLZ- und Restferien-Ampeln koennen gefiltert werden."] = "समय-संतुलन और अवकाश की स्थिति को फ़िल्टर किया जा सकता है।",
                ["Periodenvergleich zeigt die wichtigsten Vorjahreswerte, soweit Daten vorhanden sind."] = "अवधि तुलना प्रमुख पूर्व-वर्ष मान दिखाती है जहां डेटा उपलब्ध है।",
                ["Datenqualitaet markiert fehlende Dateien, alte Dateien und auffaellige Werte."] = "डेटा गुणवत्ता गुम फ़ाइलों, पुरानी फ़ाइलों और संदिग्ध मानों को चिह्नित करती है।",
                ["Austritte werden nach Austrittsart und Organisation gruppiert."] = "लीवरों को निकास प्रकार और संगठन के आधार पर समूहीकृत किया जाता है।",
