                ["Waehrung"] = "मुद्रा",
                ["Berechnung"] = "गणना",
                ["Varianten"] = "वेरिएंट",
                ["Varianten anzeigen"] = "वेरिएंट दिखाएं",
                ["Abgrenzung"] = "दायरा",
                ["Wert"] = "मूल्य",
                ["Diff."] = "अंतर.",
                ["IC"] = "आईसी",
                ["Diff ohne IC"] = "डिफ एक्सक्लूसिव. आईसी",
                ["Keine Referenzdaten fuer aktive Standorte gefunden."] = "सक्रिय साइटों के लिए कोई संदर्भ डेटा नहीं मिला.",
                ["Diese Seite nutzt dieselbe FinanceReconciliationService-Logik wie das lokale Testprogramm. Vergleich: Jahr 2025 aus Buchungsdatum, sonst Invoice Date, sonst Extraction Date. Das Summenfeld wird automatisch aus Sales Price/Value, DocTotalFC - VatSumFC oder DocTotal - VatSum gewaehlt; Belegkopfwerte werden pro DocEntry nur einmal gezaehlt. IC-Abzug ist eine Diagnose fuer den aktuellen Abgleich und veraendert die Originaldaten nicht."] = "यह पृष्ठ स्थानीय परीक्षण कार्यक्रम के समान ही फाइनेंसरिकोनसिलेशनसर्विस तर्क का उपयोग करता है। तुलना: पोस्टिंग तिथि से वर्ष 2025, अन्यथा चालान तिथि, अन्यथा निष्कर्षण तिथि। मूल्य फ़ील्ड स्वचालित रूप से बिक्री मूल्य/मूल्य, DocTotalFC - VatSumFC, या DocTotal - VatSum से चुना जाता है; दस्तावेज़ हेडर मान प्रति DocEntry में केवल एक बार गिने जाते हैं। आईसी कटौती वर्तमान समाधान के लिए एक नैदानिक ​​मूल्य है और मूल डेटा को नहीं बदलता है।",
                ["Sage Netto in GBP; Credit Notes negativ; Soll ist Local Currency."] = "जीबीपी में सेज नेट; क्रेडिट नोट नकारात्मक; संदर्भ स्थानीय मुद्रा है.",
                ["Sage ImporteNeto; REC/Credit Notes negativ; Zuschlaege/Nebenkosten noch pruefen."] = "ऋषि आयातनेटो; आरईसी/क्रेडिट नोट नकारात्मक; अधिभार/शुल्क की अभी भी जांच की जानी है।",
                ["Bestaetigte IT-Regel: Trafag Italia ausgeschlossen; doppelte Zeilen ohne Supplier country nur einmal."] = "पुष्टिकृत आईटी नियम: ट्रैफ़ैग इटालिया को बाहर रखा गया; आपूर्तिकर्ता देश के बिना डुप्लिकेट पंक्तियों को एक बार गिना जाता है।",
                ["Alphaplan Excel; Finance-Regeln gemäss Deutschland-Rueckmeldung: Weiterberechnungen ausgeschlossen, GS negativ, GS2510095 2024."] = "अल्फाप्लान एक्सेल; जर्मनी की प्रतिक्रिया के अनुसार वित्त नियम: रिचार्ज शामिल नहीं, क्रेडिट नोट नकारात्मक, 2024 में जीएस2510095।",
                ["Passt gegen Soll; Sales Price/Value ist bevorzugte Variante."] = "संदर्भ से मेल खाता है; विक्रय मूल्य/मूल्य पसंदीदा संस्करण है।",
                ["Vergleich gegen Local Currency Referenz."] = "स्थानीय मुद्रा संदर्भ से तुलना की गई।",
                ["Vergleich gegen Check-/Sollwert."] = "चेक/संदर्भ मान से तुलना की गई।",
                ["Pruefen"] = "जांचें",
                ["Keine Daten"] = "कोई डेटा नहीं",
                ["Journal Import (Hauptbuch)"] = "जर्नल आयात (सामान्य खाता बही)",
                ["Erster Load der Hauptbuch-Buchungszeilen je Gesellschaft in die separate Tabelle FinancialJournalEntries — Grundlage fuer Konsolidierung und Analysen. B1-Gesellschaften (FR, IT, US, IN) lesen aus OJDT/JDT1; CH/AT liest aus SAP ECC (BKPF/BSEG) ueber das OData-EntitySet FinanzJournalSet. Der Sales-Datenfluss (CentralSalesRecords) bleibt unberuehrt. Ein Lauf ersetzt den Journal-Bestand der Gesellschaft komplett; der Zeitraum folgt dem Datumsfilter aus den Export-Einstellungen."] = "प्रति कंपनी सामान्य-लेजर जर्नल लाइनों का पहला लोड अलग-अलग फाइनेंशियलजर्नलएंट्रीज़ तालिका में - समेकन और विश्लेषण के लिए आधार। बी1 कंपनियां (एफआर, आईटी, यूएस, आईएन) ओजेडीटी/जेडीटी1 से पढ़ी गईं; सीएच/एटी एसएपी ईसीसी (बीकेपीएफ/बीएसईजी) से ओडाटा इकाई सेट फिनानज़जर्नलसेट के माध्यम से पढ़ता है। बिक्री डेटा प्रवाह (CentralSalesRecords) अछूता है। एक रन कंपनी के जर्नल डेटा को पूरी तरह से बदल देता है; क्षितिज निर्यात सेटिंग्स से दिनांक फ़िल्टर का अनुसरण करता है।",
                ["Alle B1-Gesellschaften laden"] = "सभी B1 कंपनियों को लोड करें",
                ["Quellsystem"] = "स्रोत प्रणाली",
                ["Journalzeilen"] = "जर्नल पंक्तियाँ",
                ["Buchungsdatum von/bis"] = "पोस्टिंग दिनांक कब से कब तक",
                ["Letzter Load"] = "अंतिम भार",
                ["Laden"] = "लोड करें",
                ["Keine aktiven B1-/HANA-Gesellschaften gefunden."] = "कोई सक्रिय B1/HANA कंपनी नहीं मिली.",
                ["Enthalten: die B1-Gesellschaften ueber HANA (Frankreich, Italien, USA, Indien — Indien ist fachlich SAP B1, historisch aber als Quellsystem 'SAGE' angeschrieben) sowie CH/AT ueber SAP OData. Wichtig fuer CH/AT: Der Load funktioniert erst, wenn das EntitySet 'FinanzJournalSet' auf SAP-Seite bereitgestellt ist (Felddefinition: docs/FINANCE_JOURNAL_SAP_ODATA_SPEZ_2026-07-14.md); bis dahin meldet der Lauf eine klare Fehlermeldung. Nicht enthalten: die Manual-Excel-Laender DE/UK/ES."] = "शामिल हैं: हाना के माध्यम से बी1 कंपनियां (फ्रांस, इटली, अमेरिका, भारत - भारत सार रूप में एसएपी बी1 है लेकिन ऐतिहासिक रूप से इसे 'एसएजीई' कहा जाता है) प्लस एसएपी ओडाटा के माध्यम से सीएच/एटी। सीएच/एटी के लिए महत्वपूर्ण: लोड केवल तभी काम करता है जब एसएपी पक्ष पर इकाई सेट 'फिनानजजर्नलसेट' प्रदान किया जाता है (फ़ील्ड परिभाषा: दस्तावेज़/FINANCE_JOURNAL_SAP_ODATA_SPEZ_2026-07-14.md); तब तक रन एक स्पष्ट त्रुटि की रिपोर्ट करता है। शामिल नहीं: मैनुअल एक्सेल देश DE/UK/ES।",
