                ["Lieferant aufklappen zeigt den Spend nach Warengruppe, Warengruppe aufklappen die einzelnen Materialnummern. Warengruppe aus dem Materialstamm (MARA-MATKL), Fallback Beleg-Warengruppe. Je Warengruppe werden die 25 groessten Materialien gezeigt, der Rest steht in \"uebrige\"."] = "आपूर्तिकर्ता का विस्तार सामग्री समूह द्वारा खर्च दिखाता है; किसी सामग्री समूह का विस्तार करना व्यक्तिगत सामग्री संख्याओं को दर्शाता है। सामग्री मास्टर (MARA-MATKL) से सामग्री समूह, दस्तावेज़ समूह में फ़ॉलबैक। प्रति सामग्री समूह में 25 सबसे बड़ी सामग्रियां दिखाई गई हैं, बाकी \"यूब्रिगे\" में हैं।",
