                ["Wartet auf SAP"] = "एसएपी का इंतजार है",
                ["Spend-Aufriss (mehrstufig)"] = "व्यय विवरण (बहु-स्तरीय)",
                ["Perspektive waehlen, dann stufenweise aufklappen. Je Ebene sind die groessten Positionen einzeln, der Rest steckt in einer 'uebrige'-Zeile - die Elternsumme bleibt dadurch die Summe ihrer Kinder. Warengruppe aus Materialstamm (MARA-MATKL), Fallback Bestellbeleg."] = "एक परिप्रेक्ष्य चुनें, फिर स्तर दर स्तर विस्तार करें। प्रत्येक स्तर सबसे बड़े पदों को व्यक्तिगत रूप से सूचीबद्ध करता है, बाकी को 'शेष' पंक्ति में बंडल किया जाता है - इसलिए मूल कुल हमेशा अपने बच्चों के योग के बराबर होता है। मटेरियल मास्टर (MARA-MATKL) से मटेरियल ग्रुप, फ़ॉलबैक खरीद दस्तावेज़।",
