                ["Spend CHF, offene Menge, offener Wert, Kontraktwert, Beleganzahl, Lieferantenanzahl, letzter Refresh."] = "सीएचएफ खर्च करें, खुली मात्रा, खुला मूल्य, अनुबंध मूल्य, ऑर्डर गिनती, आपूर्तिकर्ता गिनती, नवीनतम ताज़ा।",
                ["Service/Cache fuer periodische Aggregation bauen; Filter fuer Jahr/Von-Bis/Lieferant/Warengruppe; Belegarten fuer Bestellung vs. Kontrakt trennen."] = "आवधिक एकत्रीकरण के लिए सेवा/कैश बनाएं; वर्ष/से-से/आपूर्तिकर्ता/सामग्री समूह के लिए फ़िल्टर; ऑर्डर बनाम अनुबंध के लिए अलग-अलग दस्तावेज़ प्रकार।",
                ["Naechster Schritt: Datenmodell fuer Aggregation definieren und EKPO/EKET Vollabzug gegen SAP testen."] = "अगला चरण: एकत्रीकरण डेटा मॉडल को परिभाषित करें और SAP के विरुद्ध पूर्ण EKPO/EKET निष्कर्षण का परीक्षण करें।",
                ["Startpunkt"] = "प्रारंभिक बिंदु",
                ["Aggregationsmodell"] = "एकत्रीकरण मॉडल",
                ["Zieltabelle oder Cache fuer Spend, offene Werte und offene Mengen definieren."] = "व्यय, खुले मूल्यों और खुली मात्राओं के लिए लक्ष्य तालिका या कैश को परिभाषित करें।",
                ["Filterlogik"] = "फ़िल्टर तर्क",
                ["Jahr, Von/Bis, Lieferant, Warengruppe und Artikel als Standardfilter vorbereiten."] = "वर्ष, से/तक, आपूर्तिकर्ता, सामग्री समूह और लेख को मानक फ़िल्टर के रूप में तैयार करें।",
                ["Performance"] = "प्रदर्शन",
                ["Dashboard liest Aggregatwerte, nicht bei jedem Seitenaufruf alle SAP-Zeilen."] = "डैशबोर्ड प्रत्येक पृष्ठ अनुरोध पर सभी SAP पंक्तियों के बजाय समग्र मान पढ़ता है।",
                ["ideen/liefertermin-risiko"] = "लिफ़रटर्मिन-रिसिको",
                ["Delivery due-date risk"] = "सोफोर्टनट्ज़न ऑस ईकेईटी।",
