                ["Naechster Schritt: eigene Seite mit Faelligkeitskalender, Rueckstands-Hotlist und Lieferant/Artikel-Drilldown bauen."] = "अगला चरण: नियत तिथि कैलेंडर, अतिदेय हॉटलिस्ट और आपूर्तिकर्ता/आर्टिकल ड्रिलडाउन के साथ अपना पेज बनाएं।",
                ["Datumsklassen"] = "खजूर की बाल्टियाँ",
                ["Ueberfaellig, 0-7 Tage, 8-30 Tage und spaeter als Standardklassen."] = "अतिदेय, 0-7 दिन, 8-30 दिन और बाद में मानक कक्षाओं के रूप में।",
                ["Bewertung"] = "मूल्यांकन",
                ["Offene EKET-Mengen mit EKPO-Netto-Stueckwert bewerten."] = "ईकेपीओ शुद्ध इकाई मूल्य के साथ खुली ईकेईटी मात्राओं का मूल्य निर्धारण करें।",
