                ["Netto-Stueckpreis als Netwr/Menge bilden und Minimum je Artikel/Jahr ausweisen."] = "शुद्ध इकाई मूल्य की गणना नेटवर्क/मात्रा के रूप में करें और लेख/वर्ष के अनुसार न्यूनतम दिखाएं।",
                ["Naechster Schritt: Lieferantennamen aus Data-Quelle mitcachen."] = "अगला चरण: डेटा स्रोत से कैश आपूर्तिकर्ता नाम।",
