                ["PowerBI aggregiert mit Min(Netwr CHF/Stk)."] = "पावर बीआई न्यूनतम (नेटवर्क सीएचएफ/यूनिट) के साथ एकत्रित होता है।",
                ["ideen/spend-konzentration"] = "खर्च-कोन्जेनट्रेशन",
                ["Spend concentration"] = "लीफेरेंतेनाभाएंगिगकेइट और बुएन्डेलुंगस्पोटेन्ज़ियल।",
                ["Supplier dependency and bundling potential."] = "लाइफ़रेंट और वेरेनग्रुप वर्डिचेट पर एक बार खर्च करें, टॉप-लाइफ़रेंटेनटाइल, सिंगल-सोर्स-रिसिकेन और फ्रैगमेंटियरंग सिचटबार ज़ू मशीन।",
                ["Spend is aggregated by supplier and material group to show top supplier shares, single-source risks and fragmentation."] = "EKPO.Netwr, EKPO.Matkl, EKKO.Lifnr, Lieferantenname, Warengruppentext",
