                ["Buendelung"] = "बंडलिंग",
                ["Warengruppen mit hohem Buendelungspotenzial hervorheben."] = "उच्च बंडलिंग क्षमता वाले सामग्री समूहों को उजागर करें।",
                ["ideen/datenqualitaet"] = "डेटेनक्वालिटेट एइंकॉफ़",
                ["Purchasing data quality"] = "इनकॉफ़्स्केन्नज़हलेन सिचर्न में वर्ट्राउएन।",
                ["Secure trust in purchasing KPIs."] = "स्टैमडेटेन और मैपिंग-ल्यूकेन को एक वर्ष से अधिक की योग्यता प्राप्त करने के लिए कहा जाता है, जो कि विश्लेषण के आधार पर गलत है।",
                ["Missing master data and mapping gaps are shown as dedicated quality KPIs so wrong analyses are detected early."] = "EKKO, EKPO, EKET, लीफ़रेंटेनमैपिंग, वेयरेंग्रुपपेनमैपिंग, आर्टिकेलटेक्स्ट",
                ["Mapping-Abdeckung %, fehlende Warengruppe, fehlender Artikeltext, fehlender Lieferant, Nullpreis."] = "मैपिंग कवरेज%, गायब सामग्री समूह, गायब लेख पाठ, लापता आपूर्तिकर्ता, शून्य कीमत।",
