                ["Naechster Schritt: Pflichtfeldkatalog fuer Einkauf definieren und Datenqualitaetsampel bauen."] = "अगला चरण: आवश्यक-फ़ील्ड कैटलॉग की खरीद को परिभाषित करें और डेटा गुणवत्ता ट्रैफ़िक लाइट का निर्माण करें।",
                ["Pflichtfelder"] = "आवश्यक फ़ील्ड",
                ["Ebeln, Ebelp, Matnr, Matkl, Menge, Netwr, Lifnr pruefen."] = "Ebeln, Ebelp, Matnr, Matkl, Menge, Netwr, Lifnr की जाँच करें।",
                ["Mappingquote"] = "मानचित्रण दर",
                ["Warengruppen- und Lieferantenmapping pro Quelle messen."] = "प्रति स्रोत सामग्री समूह और आपूर्तिकर्ता मानचित्रण को मापें।",
