                ["EKKO, EKPO, EKET, Lieferantenstamm, optional Reklamationen"] = "रिसिको-स्कोर 0-100, टॉप-10-अभेंगिगकेइट, ऑफनर वर्ट जे लिफेरेंट, यूबरफैलिगे मेंगे।",
                ["risk score 0-100, top-10 dependency, open value by supplier, overdue quantity."] = "स्पेंड-एंटील, अनज़हल ऑफेनन बेलेगेन, टर्मिन्र्यूकस्टैंड, सिंगल-सोर्स-हिनवीस और डेटनक्वालिटेट से प्राप्त लाभ।",
                ["Weighted score from spend share, open order count, schedule delay, single-source marker and data quality."] = "एम्पेलमैट्रिक्स लिफ़रेंट x वारेनग्रुप, रिसिको-हॉटलिस्ट, 3डी-राउम स्पेंड/रुएकस्टैंड/स्कोर।",
                ["traffic-light matrix supplier x material group, risk hotlist, 3D space spend/delay/score."] = "नेचस्टर श्रिट: ईकेपीओ/ईकेईटी वोलाग्रिगेशन प्रो लीफेरेंट औफबाउएन अंड स्कोर-गेविचटुंग फैक्लिच मिट एइंकौफ फेस्टलेगेन।",
                ["PowerBI-Preislogik nach Artikel und Jahr."] = "लेख और वर्ष के अनुसार पावर बीआई मूल्य तर्क।",
