                ["EKPO.Netwr, EKPO.Menge, EKPO.Matnr, EKPO.Txz01, EKKO.Bedat"] = "न्यूनतम (नेटवर्क सीएचएफ/एसटीके), आर्टिकेल, जहर, लिफेरेंटेंसलाइसर।",
                ["Min(Netwr CHF/unit), article, year, supplier slicer."] = "स्टुकेपेरिस = नेट्टो / मेंगे, पावरबीआई के लिए न्यूनतम उत्पाद/जहर।",
                ["Unit price = net / quantity, then minimum by article/year like Power BI."] = "वर्ष से पहले, लेख-हॉटलिस्ट, लेख को सत्यापित करें।",
