                ["EKKO, EKPO, Kontrakte, Preferred-Supplier-Liste"] = "मेवरिक-एंटील %, वर्ट ऑसरहाल्ब वर्ट्रैग, अंजाहल रेगेल्वरलेटज़ुंगेन, बेट्रोफीन वेरेनग्रुपपेन।",
                ["maverick share %, value outside contract, rule violation count, affected material groups."] = "बेस्टेलपोज़िशन गेगेन वर्ट्रैग्स-/पसंदीदा-आपूर्तिकर्ता-रेगेलन मैचेन अंड एबवेइचुंगेन ग्रुपिएरेन।",
                ["Match order items against contract/preferred-supplier rules and group deviations."] = "अनुपालन-फ़नल, एबवेइचुंगस्टेबेल, हीटमैप आइंकाएउफ़र x वारेनग्रुप।",
                ["compliance funnel, deviation table, heatmap purchaser x material group."] = "नेचस्टर श्रिट: पसंदीदा-आपूर्तिकर्ता- और वर्ट्रैग्सरेगेलन और स्टैमडेटेनक्वेल निश्चित।",
                ["Next step: define preferred supplier and contract rules as master-data source."] = "Konzept",
                ["Kontrakte, Abrufe und Restmengen steuern."] = "अनुबंध, कॉल-ऑफ़ और शेष मात्राएँ प्रबंधित करें।",
                ["Mengenkontrakte so auswerten, dass Restmenge, Restwert und Verfallsrisiko aktiv steuerbar werden."] = "मात्रा अनुबंधों का मूल्यांकन करें ताकि शेष मात्रा, शेष मूल्य और समाप्ति जोखिम प्रबंधनीय हो जाएं।",
                ["EKKO, EKPO, EKET, Vertragsbelegarten"] = "एब्रुफ़कोट %, रेस्टमेंज, रेस्टवर्ट सीएचएफ, लॉफज़िट, फेलिज वर्पफ्लिचटुंग।",
