                ["Abgrenzung"] = "Fushëveprimi",
                ["Wert"] = "Vlera",
                ["Diff."] = "Ndryshim.",
                ["IC"] = "IC",
                ["Diff ohne IC"] = "Ndryshimet përjashtohen. IC",
                ["Keine Referenzdaten fuer aktive Standorte gefunden."] = "Nuk u gjetën të dhëna referimi për faqet aktive.",
                ["Diese Seite nutzt dieselbe FinanceReconciliationService-Logik wie das lokale Testprogramm. Vergleich: Jahr 2025 aus Buchungsdatum, sonst Invoice Date, sonst Extraction Date. Das Summenfeld wird automatisch aus Sales Price/Value, DocTotalFC - VatSumFC oder DocTotal - VatSum gewaehlt; Belegkopfwerte werden pro DocEntry nur einmal gezaehlt. IC-Abzug ist eine Diagnose fuer den aktuellen Abgleich und veraendert die Originaldaten nicht."] = "Kjo faqe përdor të njëjtën logjikë FinanceReconciliationService si programi lokal i testimit. Krahasimi: viti 2025 nga data e postimit, ndryshe data e faturës, ndryshe data e nxjerrjes. Fusha e vlerës zgjidhet automatikisht nga Çmimi/Vlera e Shitjes, DocTotalFC - VatSumFC, ose DocTotal - VatSum; Vlerat e kokës së dokumentit numërohen vetëm një herë për DocEntry. Zbritja e IC është një vlerë diagnostike për rakordimin aktual dhe nuk ndryshon të dhënat origjinale.",
                ["Sage Netto in GBP; Credit Notes negativ; Soll ist Local Currency."] = "Rrjeta e sherebelës në GBP; notat e kreditit negative; referenca është monedha vendase.",
                ["Sage ImporteNeto; REC/Credit Notes negativ; Zuschlaege/Nebenkosten noch pruefen."] = "Sage ImporteNeto; REC/notat e kreditit negative; shtesë / tarifa ende për t'u kontrolluar.",
                ["Bestaetigte IT-Regel: Trafag Italia ausgeschlossen; doppelte Zeilen ohne Supplier country nur einmal."] = "Rregulli i konfirmuar i IT: Trafag Italia përjashtohet; rreshtat dublikatë pa shtetin furnizues numërohen një herë.",
                ["Alphaplan Excel; Finance-Regeln gemäss Deutschland-Rueckmeldung: Weiterberechnungen ausgeschlossen, GS negativ, GS2510095 2024."] = "Alphaplan Excel; rregullat e financave për përgjigjen e Gjermanisë: rimbushjet e përjashtuara, shënimet e kredisë negative, GS2510095 në 2024.",
                ["Passt gegen Soll; Sales Price/Value ist bevorzugte Variante."] = "Referenca e ndeshjeve; Çmimi/Vlera e Shitjes është varianti i preferuar.",
                ["Vergleich gegen Local Currency Referenz."] = "Krahasuar me referencën e monedhës vendase.",
                ["Vergleich gegen Check-/Sollwert."] = "Krahasuar me vlerën e kontrollit/referencës.",
                ["Pruefen"] = "Kontrollo",
                ["Keine Daten"] = "Nuk ka të dhëna",
                ["Journal Import (Hauptbuch)"] = "Importi i ditarit (libri kryesor)",
                ["Erster Load der Hauptbuch-Buchungszeilen je Gesellschaft in die separate Tabelle FinancialJournalEntries — Grundlage fuer Konsolidierung und Analysen. B1-Gesellschaften (FR, IT, US, IN) lesen aus OJDT/JDT1; CH/AT liest aus SAP ECC (BKPF/BSEG) ueber das OData-EntitySet FinanzJournalSet. Der Sales-Datenfluss (CentralSalesRecords) bleibt unberuehrt. Ein Lauf ersetzt den Journal-Bestand der Gesellschaft komplett; der Zeitraum folgt dem Datumsfilter aus den Export-Einstellungen."] = "Ngarkimi i parë i linjave të ditarit të librit kryesor për kompani në tabelën e veçantë të Regjistrimeve të Ditarit Financiar - bazë për konsolidimin dhe analitikën. Kompanitë B1 (FR, IT, SHBA, IN) lexuar nga OJDT/JDT1; CH/AT lexohet nga SAP ECC (BKPF/BSEG) nëpërmjet grupit të entitetit OData FinanzJournalSet. Rrjedha e të dhënave të shitjeve (CentralSalesRecords) është e paprekur. Një ekzekutim zëvendëson plotësisht të dhënat e ditarit të kompanisë; horizonti ndjek filtrin e datës nga cilësimet e eksportit.",
                ["Alle B1-Gesellschaften laden"] = "Ngarko të gjitha kompanitë B1",
                ["Quellsystem"] = "Sistemi burimor",
                ["Journalzeilen"] = "Rreshtat e ditarit",
                ["Buchungsdatum von/bis"] = "Data e postimit nga/deri",
                ["Letzter Load"] = "Ngarkesa e fundit",
                ["Laden"] = "Ngarkoni",
                ["Keine aktiven B1-/HANA-Gesellschaften gefunden."] = "Nuk u gjet asnjë kompani aktive B1/HANA.",
                ["Enthalten: die B1-Gesellschaften ueber HANA (Frankreich, Italien, USA, Indien — Indien ist fachlich SAP B1, historisch aber als Quellsystem 'SAGE' angeschrieben) sowie CH/AT ueber SAP OData. Wichtig fuer CH/AT: Der Load funktioniert erst, wenn das EntitySet 'FinanzJournalSet' auf SAP-Seite bereitgestellt ist (Felddefinition: docs/FINANCE_JOURNAL_SAP_ODATA_SPEZ_2026-07-14.md); bis dahin meldet der Lauf eine klare Fehlermeldung. Nicht enthalten: die Manual-Excel-Laender DE/UK/ES."] = "Përfshihen: kompanitë B1 nëpërmjet HANA (Francë, Itali, SHBA, Indi - India është SAP B1 në thelb, por historikisht etiketuar 'SAGE') plus CH/AT nëpërmjet SAP OData. E rëndësishme për CH/AT: ngarkesa funksionon vetëm pasi grupi i entitetit 'FinanzJournalSet' ofrohet në anën e SAP (përkufizimi i fushës: docs/FINANCE_JOURNAL_SAP_ODATA_SPEZ_2026-07-14.md); deri atëherë ekzekutimi raporton një gabim të qartë. Nuk përfshihen: manuali Excel vendet DE/MB/ES.",
