                ["SAP OData Verbindung fehlgeschlagen"] = "Lidhja SAP OData dështoi",
                ["Kaskadierung Lieferant / Jahr"] = "Furnizuesi / kaskada e vitit",
                ["Lieferant aufklappen zeigt den Spend nach Warengruppe, Warengruppe aufklappen die einzelnen Materialnummern. Warengruppe aus dem Materialstamm (MARA-MATKL), Fallback Beleg-Warengruppe. Je Warengruppe werden die 25 groessten Materialien gezeigt, der Rest steht in \"uebrige\"."] = "Zgjerimi i një furnizuesi tregon shpenzimet sipas grupit të materialeve; zgjerimi i një grupi material tregon numrat individualë të materialit. Grupi i materialeve nga masteri i materialit (MARA-MATKL), kthim në grupin e dokumenteve. Për grup materiale tregohen 25 materialet më të mëdha, pjesa tjetër është në \"uebrige\".",
                ["Warengruppen auf-/zuklappen"] = "Zgjero/palos grupet e materialeve",
