                ["Simulation aktiv"] = "Simulimi aktiv",
                ["Wartet auf SAP"] = "Në pritje të SAP",
                ["Spend-Aufriss (mehrstufig)"] = "Analiza e shpenzimeve (me shumë nivele)",
                ["Perspektive waehlen, dann stufenweise aufklappen. Je Ebene sind die groessten Positionen einzeln, der Rest steckt in einer 'uebrige'-Zeile - die Elternsumme bleibt dadurch die Summe ihrer Kinder. Warengruppe aus Materialstamm (MARA-MATKL), Fallback Bestellbeleg."] = "Zgjidhni një perspektivë, më pas zgjeroni nivel pas niveli. Secili nivel rendit pozicionet më të mëdha individualisht, pjesa tjetër është e bashkuar në një rresht \"të mbetur\" - kështu që një total prindi është gjithmonë i barabartë me shumën e fëmijëve të tij. Grupi i materialeve nga masteri i materialit (MARA-MATKL), dokument blerjeje rezervë.",
