                ["Kuchen je Warengruppe: Anteil nach Beschaffungsregion"] = "Byrek sipas grupit të materialit: ndani sipas rajonit të prokurimit",
                ["Je Top-Warengruppe der CHF-Anteil je Lieferantenland. Region = Land des Lieferanten (LFA1-Land1)."] = "Për grupin kryesor të materialeve, pjesa e CHF-së sipas vendit furnizues. Rajoni = vendi furnizues (LFA1 Toka1).",
                ["Lieferantenland (SupplierCountry) ist im Cache noch leer. Die Kuchen fuellen sich mit dem naechsten Einkauf-Full-Load."] = "Vendi i furnizuesit është ende bosh në memorien specifike. Byrekët mbushen me ngarkesën e plotë të blerjes së radhës.",
                ["Volumen nach ABC"] = "Vëllimi nga ABC",
                ["ABC-Kennzeichen aus dem Materialstamm (MARC-MAABC). Fuellt sich mit dem naechsten Einkauf-Full-Load."] = "Treguesi ABC nga masteri i materialit (MARC-MAABC). Mbushet me ngarkesën e plotë të blerjes tjetër.",
