                ["Spend je Warengruppe sortieren, kumulierten Anteil berechnen und Lieferantenkonzentration klassieren."] = "renditni shpenzimet sipas grupit të materialeve, llogarisni pjesën kumulative dhe klasifikoni përqendrimin e furnitorëve.",
                ["Naechster Schritt: Pareto-Ansicht und Treemap fuer Lieferant/Warengruppe bauen."] = "Hapi tjetër: ndërtoni pamjen Pareto dhe hartën e pemëve për furnizuesin/grupin e materialit.",
