                ["Purchasing data quality"] = "Vertrauen në die Einkaufskennzahlen sichern.",
                ["Secure trust in purchasing KPIs."] = "Fehlende Stammdaten und Mapping-Luecken janë të eigene Qualitaetskennzahlen angezeigt, damit falsche Analysen frueh auffallen.",
                ["Missing master data and mapping gaps are shown as dedicated quality KPIs so wrong analyses are detected early."] = "EKKO, EKPO, EKET, Lieferantenmapping, Warengruppenmapping, Artikeltext",
                ["Mapping-Abdeckung %, fehlende Warengruppe, fehlender Artikeltext, fehlender Lieferant, Nullpreis."] = "mbulimi i hartës %, grupi i materialeve që mungon, teksti i artikullit mungon, furnizuesi mungon, çmimi zero.",
                ["Pflichtfelder zaehlen, Leerwerte klassieren, Mappingtreffer berechnen und Fehler nach Auswirkung priorisieren."] = "numëroni fushat e kërkuara, klasifikoni vlerat boshe, llogaritni goditjet e hartës dhe jepni përparësi gabimeve sipas ndikimit.",
                ["Naechster Schritt: Pflichtfeldkatalog fuer Einkauf definieren und Datenqualitaetsampel bauen."] = "Hapi tjetër: përcaktoni blerjen e katalogut të fushës së kërkuar dhe ndërtoni semaforin me cilësi të të dhënave.",
