                ["Fehlerwirkung"] = "Ndikimi i gabimit",
                ["Fehler nach betroffenem Spend oder offenem Wert priorisieren."] = "prioritizoni gabimet sipas shpenzimeve të prekura ose vlerës së hapur.",
                ["Abhaengigkeit und Lieferfaehigkeit in einem Score."] = "Varësia dhe aftësia e ofrimit në një pikë.",
                ["Einen fruehen Warnindikator fuer kritische Lieferanten schaffen, bevor offene Termine oder Single-Source-Abhaengigkeit operativ eskalieren."] = "Krijoni një tregues të paralajmërimit të hershëm për furnitorët kritikë përpara se oraret e hapura ose varësia nga një burim të vetëm të përshkallëzohet operacionalisht.",
                ["EKKO, EKPO, EKET, Lieferantenstamm, optional Reklamationen"] = "Risiko-Rezultati 0-100, Top-10-Abhaengigkeit, sulmuesi Wert je Lieferant, ueberfaellige Menge.",
                ["risk score 0-100, top-10 dependency, open value by supplier, overdue quantity."] = "Gewichtung aus Spend-Anteil, Anzahl offenen Belegen, Terminrueckstand, Single-Source-Hinweis und Datenqualitaet.",
                ["Weighted score from spend share, open order count, schedule delay, single-source marker and data quality."] = "Ampelmatrix Lieferant x Warengruppe, Risiko-Hotlist, 3D-Raum Spend/Rueckstand/Score.",
                ["traffic-light matrix supplier x material group, risk hotlist, 3D space spend/delay/score."] = "Naechster Schritt: EKPO/EKET Vollaggregation pro Lieferant aufbauen und Score-Gewichtung fachlich mit Einkauf festlegen.",
