                ["Min(Netwr CHF/unit), article, year, supplier slicer."] = "Stueckpreis = Netto / Menge, të dhëna minimale për Artikel/Jahr wie PowerBI.",
                ["Unit price = net / quantity, then minimum by article/year like Power BI."] = "Pivot nach Jahr, Artikel-Hotlist, Verlaufslinie je Artikel.",
                ["pivot by year, article hotlist, trend line by article."] = "Naechster Schritt: Lieferanten- und Warengruppennamen aus Data/Data2 als Mapping anbinden.",
                ["Einkauf ausserhalb Standards erkennen."] = "Zbuloni blerjen e standardeve të jashtme.",
                ["Bestellungen sichtbar machen, die ausserhalb bevorzugter Lieferanten, Kontrakte oder Warengruppenregeln laufen."] = "Trego porositë që dalin jashtë furnizuesve të preferuar, kontratave ose rregullave të grupit të materialeve.",
                ["EKKO, EKPO, Kontrakte, Preferred-Supplier-Liste"] = "Maverick-Anteil %, Wert ausserhalb Vertrag, Anzahl Regelverletzungen, Betroffene Warengruppen.",
