                ["compliance funnel, deviation table, heatmap purchaser x material group."] = "Naechster Schritt: Preferred-Supplier- und Vertragsregeln als Stammdatenquelle definieren.",
                ["Next step: define preferred supplier and contract rules as master-data source."] = "Konzept",
                ["Kontrakte, Abrufe und Restmengen steuern."] = "Menaxhoni kontratat, thirrjet dhe sasitë e mbetura.",
