                ["EKKO, EKPO, EKET, Vertragsbelegarten"] = "Abrufquote %, Restmenge, Restwert CHF, Laufzeit, faellige Verpflichtung.",
                ["consumption rate %, remaining quantity, remaining value CHF, term, due commitment."] = "Kontraktpositionen von normalen Bestellungen trennen und EKET-Mengen gegen Bestell-/Abrufmenge rechnen.",
