                ["contract cockpit, remaining-term traffic light, supplier/article ranking."] = "Naechster Schritt: SAP-Belegarten und Kennzeichen fuer Kontrakte mit Einkauf/SAP klaeren.",
                ["Cash-Wirkung offener Bestellungen prognostizieren."] = "Parashikimi i efektit në para të porosive të hapura.",
                ["Aus offenen Bestellungen und Faelligkeiten ableiten, wann Einkaufs-Cash-Abfluss oder Lageraufbau zu erwarten ist."] = "Përdorni porositë e hapura dhe datat e duhura për të nxjerrë rrjedhjen e pritshme të parave të blerjes ose grumbullimin e inventarit.",
