                ["Lieferant aufklappen zeigt den Spend nach Warengruppe, Warengruppe aufklappen die einzelnen Materialnummern. Warengruppe aus dem Materialstamm (MARA-MATKL), Fallback Beleg-Warengruppe. Je Warengruppe werden die 25 groessten Materialien gezeigt, der Rest steht in \"uebrige\"."] = "Bir tedarikçinin genişletilmesi, malzeme grubuna göre harcamayı gösterir; bir malzeme grubunun genişletilmesi, bireysel malzeme numaralarını gösterir. Malzeme ana verisinden (MARA-MATKL) malzeme grubu, belge grubuna geri dönüş. Malzeme grubu başına en büyük 25 malzeme gösterilmektedir, geri kalanı \"uebrige\" içindedir.",
