                ["Bestellungen sichtbar machen, die ausserhalb bevorzugter Lieferanten, Kontrakte oder Warengruppenregeln laufen."] = "Tercih edilen tedarikçilerin, sözleşmelerin veya malzeme grubu kurallarının dışında çalışan siparişleri gösterin.",
                ["EKKO, EKPO, Kontrakte, Preferred-Supplier-Liste"] = "Maverick-Anteil %, Wert ausserhalb Vertrag, Anzahl Regelverletzungen, betroffene Warengruppen.",
                ["maverick share %, value outside contract, rule violation count, affected material groups."] = "En iyi konumlar, En İyi/Tercih Edilen Tedarikçi-Regeln eşleşmeleri ve farklı gruplamalardır.",
                ["Match order items against contract/preferred-supplier rules and group deviations."] = "Uyumluluk Hunisi, Abweichungstabelle, Isı Haritası Einkaeufer x Warengruppe.",
                ["compliance funnel, deviation table, heatmap purchaser x material group."] = "Naechster Schritt: Tercih Edilen Tedarikçi ve Stammdatenquelle tanımlayıcı olarak Vertragsregeln.",
                ["Next step: define preferred supplier and contract rules as master-data source."] = "Konzept",
                ["Kontrakte, Abrufe und Restmengen steuern."] = "Sözleşmeleri, çağrıları ve kalan miktarları yönetin.",
                ["Mengenkontrakte so auswerten, dass Restmenge, Restwert und Verfallsrisiko aktiv steuerbar werden."] = "Miktar sözleşmelerini, kalan miktarın, kalan değerin ve vade riskinin yönetilebilir hale gelmesi için değerlendirin.",
                ["EKKO, EKPO, EKET, Vertragsbelegarten"] = "Abrufquote %, Restmenge, Restwert CHF, Laufzeit, faellige Verpflichtung.",
                ["consumption rate %, remaining quantity, remaining value CHF, term, due commitment."] = "Normal Bestellungen trennen ve EKET-Mengen gegen Bestell-/Abrufmenge Rehnen'in kontraktozisyonu.",
                ["Separate contract items from normal orders and calculate EKET quantities against ordered/called-off quantity."] = "Kontrakt-Kokpit, Ampel Restlaufzeit, Teğmen/Artikel-Sıralaması.",
                ["contract cockpit, remaining-term traffic light, supplier/article ranking."] = "Naechster Schritt: SAP-Belegarten ve Kennzeichen, Einkauf/SAP ile sözleşme imzaladı.",
                ["Cash-Wirkung offener Bestellungen prognostizieren."] = "Açık emirlerin nakit etkisini tahmin edin.",
                ["Aus offenen Bestellungen und Faelligkeiten ableiten, wann Einkaufs-Cash-Abfluss oder Lageraufbau zu erwarten ist."] = "Beklenen satın alma nakit çıkışını veya envanter oluşumunu elde etmek için açık siparişleri ve vade tarihlerini kullanın.",
                ["EKPO, EKET, FI/AP, Zahlungsbedingungen"] = "Nakit Tahmini CHF, Faelliger Offener Wert, Rueckstandswert, Monatsbedarf.",
                ["cash forecast CHF, due open value, overdue value, monthly requirement."] = "Offenen Wert aus EKET/EKPO berechnen ve nach Faelligkeitsmonat artı Zahlungsziel verschieben.",
                ["Calculate open value from EKET/EKPO and shift by due month plus payment terms."] = "Monatskurve, Cash-Kalender, Teğmen ve Groesster Cash-Wirkung.",
                ["monthly curve, cash calendar, supplier with highest cash impact."] = "Naechster Schritt: Zahlungsbedingungen/FI-Quelle, Standard-Zahlungsziel ile aynı anda birleştirilmiş veya birleştirilmiş.",
                ["Next step: connect payment terms/FI source or start with standard payment-term simulation."] = "Konzept",
                ["Luecken in Einkaufsdaten sichtbar machen."] = "Satın alma verilerindeki boşlukları görünür hale getirin.",
                ["Fehlende oder falsche Stammdaten erkennen, damit Kennzahlen belastbar werden."] = "Eksik veya yanlış ana verileri tespit ederek KPI'ların güvenilir olmasını sağlayın.",
                ["EKKO, EKPO, EKET, Lieferanten-/Warengruppenmapping"] = "Mapping-Abdeckung %, fehlende Warengruppe, fehlender Artikeltext, Preisbasis fehlt, Dubletten.",
