                ["Stuecklistenanalyse (ZLO03)"] = "BOM poj (ZLO03)",
                ["Laedt die Stuecklistenanalyse des SAP-Reports ZM_LZCODE20_OPT (ZPOWERBI_VC_TXT/ZMD04_CALC) ueber den Gateway-Service ZPOWERBI_EINKAUF_SRV in den lokalen Cache (MaterialUsageCache). Eine Zeile je Kopfmaterial/Komponente-Paar inkl. Bestand, Stueckkosten und Exklusivitaet. SAP erzwingt einen Materialfilter — ohne Eingabe wird bewusst ALLES geladen (Catch-all)."] = "De' qem BOM poj SAP ja' ZM_LZCODE20_OPT (ZPOWERBI_VC_TXT/ZMD04_CALC) lo'taHvIS gateway toy'wI' ZPOWERBI_EINKAUF_SRV De' polDaq Daq (MaterialUsageCache). wa' tlhegh Hoch header-Hap/'ay' cha' 'ej polbogh mI, unit Huch, 'ej wa' neH. SAP Hap nej — De' 'el Hutlh, Hoch De' qemlu'pu' chIch (catch-Hoch).",
