                ["Diese Seite nutzt dieselbe FinanceReconciliationService-Logik wie das lokale Testprogramm. Vergleich: Jahr 2025 aus Buchungsdatum, sonst Invoice Date, sonst Extraction Date. Das Summenfeld wird automatisch aus Sales Price/Value, DocTotalFC - VatSumFC oder DocTotal - VatSum gewaehlt; Belegkopfwerte werden pro DocEntry nur einmal gezaehlt. IC-Abzug ist eine Diagnose fuer den aktuellen Abgleich und veraendert die Originaldaten nicht."] = "rap FinanceReconciliationService logic lo' ghItlhvam. rapmoH: DIS 2025 vo' ghItlh jaj, pagh malja nav jaj, pagh extract jaj. lo'laHghach yotlh wIv 'oH'egh vo' ngev ngevmeH mI'/lo'laHghach, DocTotalFC - VatSumFC, pagh DocTotal - VatSum; ghItlh header lo'laHghach toghlu' wa'logh neH Hoch DocEntry. IC deduction 'oH diagnostic lo'laHghach 'ej choHbe' De' wa'DIch.",
